Path("templates/use_cases/second_approval_review.html").write_text(
    '''{% extends "base.html" %}\n{% block title %}Zweitprüfung – {{ use_case.short_id }}{% endblock %}\n{% block content %}\n<div class="page-header">\n  <div>\n    <div class="eyebrow mb-2">{{ use_case.short_id }} · Unabhängige Zweitprüfung</div>\n    <h1 class="page-title">{{ use_case.title }}</h1>\n    <p class="page-subtitle">Die Zuweisung benennt die bevorzugte prüfende Person. Jede andere ebenfalls unabhängige und berechtigte Person kann die Aufgabe übernehmen.</p>\n  </div>\n  <a class="btn btn-outline-secondary" href="{{ use_case.get_absolute_url }}">Zum Use Case</a>\n</div>\n\n<div class="kpi-strip mb-4">\n  <div class="kpi-cell"><small>Status</small><strong>{% if decision.is_final %}Bestätigt{% elif decision.is_returned_from_second_approval %}Zurückgegeben{% else %}Ausstehend{% endif %}</strong></div>\n  <div class="kpi-cell"><small>Bevorzugt zugewiesen</small><strong>{{ decision.second_approval_assignee|default:"Nicht dokumentiert" }}</strong></div>\n  <div class="kpi-cell"><small>Prüfauftrag seit</small><strong>{{ decision.second_approval_requested_at|date:"d.m.Y H:i"|default:"–" }}</strong></div>\n</div>\n\n<div class="row g-4">\n  <div class="col-xl-6">\n    <section class="app-card mb-4">\n      <div class="card-header"><strong>Aktuelle Bewertung v{{ assessment.version }}</strong></div>\n      <div class="card-body">\n        <dl class="row small mb-3">\n          <dt class="col-sm-5 text-muted">Bewertende Person</dt><dd class="col-sm-7">{{ assessment.assessed_by|default:"–" }}</dd>\n          <dt class="col-sm-5 text-muted">Confidence</dt><dd class="col-sm-7">{{ assessment.confidence_label }}</dd>\n          <dt class="col-sm-5 text-muted">Empfehlung</dt><dd class="col-sm-7">{{ assessment.get_recommendation_display }}</dd>\n        </dl>\n        <p>{{ assessment.rationale }}</p>\n        <a href="{{ assessment.evidence_url }}" target="_blank" rel="noopener noreferrer">Bewertungsnachweis öffnen</a>\n      </div>\n    </section>\n  </div>\n  <div class="col-xl-6">\n    <section class="app-card mb-4">\n      <div class="card-header"><strong>Erstentscheidung</strong></div>\n      <div class="card-body">\n        <dl class="row small mb-3">\n          <dt class="col-sm-5 text-muted">Entscheidung</dt><dd class="col-sm-7">{{ decision.get_decision_status_display }}</dd>\n          <dt class="col-sm-5 text-muted">Entscheidende Person</dt><dd class="col-sm-7">{{ decision.decided_by|default:"–" }}</dd>\n          <dt class="col-sm-5 text-muted">Zeitpunkt</dt><dd class="col-sm-7">{{ decision.created_at|date:"d.m.Y H:i" }}</dd>\n        </dl>\n        <p>{{ decision.rationale }}</p>\n      </div>\n    </section>\n  </div>\n</div>\n\n<div class="row g-4">\n  <div class="col-xl-6">\n    <section class="app-card mb-4">\n      <div class="card-header"><strong>Auflagen</strong></div>\n      <div class="card-body">\n        <div class="text-preline mb-3">{{ decision.conditions }}</div>\n        <dl class="row small mb-0">\n          <dt class="col-sm-5 text-muted">Verantwortung</dt><dd class="col-sm-7">{{ decision.condition_owner|default:"–" }}</dd>\n          <dt class="col-sm-5 text-muted">Fälligkeit</dt><dd class="col-sm-7">{{ decision.condition_due_date|date:"d.m.Y"|default:"–" }}</dd>\n        </dl>\n      </div>\n    </section>\n  </div>\n  <div class="col-xl-6">\n    <section class="app-card mb-4">\n      <div class="card-header"><strong>Governance-Nachweise</strong></div>\n      <div class="card-body">\n        <dl class="row small mb-0">\n          <dt class="col-sm-7 text-muted">Governance-Vorprüfung im Assessment</dt><dd class="col-sm-5">{% if assessment.governance_precheck_completed %}Durchgeführt{% else %}Offen{% endif %}</dd>\n          <dt class="col-sm-7 text-muted">Separate Bestätigung der Erstentscheidung</dt><dd class="col-sm-5">{% if decision.governance_confirmed %}Bestätigt{% else %}Offen{% endif %}</dd>\n          <dt class="col-sm-7 text-muted">Datenschutzprüfung</dt><dd class="col-sm-5">{% if not use_case.privacy_review_required %}Nicht erforderlich{% elif use_case.privacy_review_completed %}Abgeschlossen{% else %}Offen{% endif %}</dd>\n          <dt class="col-sm-7 text-muted">Informationssicherheit</dt><dd class="col-sm-5">{% if not use_case.security_review_required %}Nicht erforderlich{% elif use_case.security_review_completed %}Abgeschlossen{% else %}Offen{% endif %}</dd>\n          <dt class="col-sm-7 text-muted">Rechtsprüfung</dt><dd class="col-sm-5">{% if not use_case.legal_review_required %}Nicht erforderlich{% elif use_case.legal_review_completed %}Abgeschlossen{% else %}Offen{% endif %}</dd>\n        </dl>\n      </div>\n    </section>\n  </div>\n</div>\n\n{% if decision.is_returned_from_second_approval %}\n<div class="alert alert-warning"><strong>Begründet zurückgegeben</strong><div class="mt-1">{{ decision.second_approval_return_reason }}</div><div class="small text-muted mt-1">{{ decision.second_approval_returned_by }} · {{ decision.second_approval_returned_at|date:"d.m.Y H:i" }}</div></div>\n{% elif decision.is_final %}\n<div class="alert alert-success"><strong>Unabhängig bestätigt</strong><div class="small mt-1">{{ decision.second_approved_by }} · {{ decision.finalized_at|date:"d.m.Y H:i" }}</div></div>\n{% elif can_act %}\n<form method="post" class="app-card">\n  {% csrf_token %}\n  <div class="card-header"><strong>Prüfentscheidung</strong><div class="small text-muted mt-1">Bestätigen finalisiert die Entscheidung. Eine Rückgabe verändert die Erstentscheidung nicht und benötigt eine Begründung.</div></div>\n  <div class="card-body">\n    {{ form.non_field_errors }}\n    <label class="form-label" for="{{ form.return_reason.id_for_label }}">{{ form.return_reason.label }}</label>\n    {{ form.return_reason }}\n    <div class="text-danger small">{{ form.return_reason.errors }}</div>\n  </div>\n  <div class="card-footer d-flex justify-content-end gap-2">\n    <button class="btn btn-outline-secondary" name="action" value="return">Begründet zurückgeben</button>\n    <button class="btn btn-primary" name="action" value="confirm">Unabhängig bestätigen</button>\n  </div>\n</form>\n{% else %}\n<div class="alert alert-secondary"><strong>Nur Ansicht</strong><div class="small mt-1">Du kannst die Prüfgrundlage einsehen, bist für diese Entscheidung aber nicht unabhängig berechtigt. Es stehen deshalb keine ausführbaren Aktionen zur Verfügung.</div></div>\n{% endif %}\n{% endblock %}\n''',
    encoding="utf-8",
)

